// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // fuzzed parameter is the caller address; the property: only the deployer (owner) can successfully call sudicideAnyone
    function testFuzz_property(address caller) public {
        // keep caller wide but avoid 0x0 which is sometimes less interesting
        vm.assume(caller != address(0));

        // fund the caller so it can send txs if needed
        vm.deal(caller, 1 wei);

        bool ok;
        // try calling sudicideAnyone as `caller`; c.sudicideAnyone is non-payable so call without value
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule the reference satisfies: only the deployer (owner) may succeed.
        // The deployer here is the test contract deployer of C, which is this test contract (setUp used new C()).
        // address(this) is the owner; calling sudicideAnyone should succeed iff caller == address(this).
        assertTrue(ok == (caller == address(this)));
    }
}
